    using System;
using System.Collections.Generic;

class GFG
{
    static List<List<int>> getSubArrays(int[] arr)
    {
        List<List<int>> ans = new List<List<int>>();
        int n = arr.Length;

        for (int i = 0; i < n; i++)
        {
            for (int j = i; j < n; j++)
            {
                List<int> subarray = new List<int>();

                for (int k = i; k <= j; k++)
                    subarray.Add(arr[k]);

                ans.Add(subarray);
            }
        }

        return ans;
    }

    static void Main()
    {
        int[] arr = { 1, 2, 3 };

        List<List<int>> ans = getSubArrays(arr);

        Console.Write("[");
        for (int i = 0; i < ans.Count; i++)
        {
            Console.Write("[");
            Console.Write(string.Join(", ", ans[i]));
            Console.Write("]");

            if (i + 1 < ans.Count)
                Console.Write(", ");
        }
        Console.Write("]");
    }
}


